-- BEGIN MODULE automation.lua
moduleBuilders["automation.lua"] = function()
    -- Hand-structured gameplay reconstructions, checked against prototype PCs.
    -- Descriptive names are inferred. Cells retain the VM's captured-variable identity.
    -- This module defines functions only and starts no task or network request.
    local M = {}
    local function get(cells,index)
        local cell=cells[index]
        return cell[3][cell[1]]
    end
    local function put(cells,index,value)
        local cell=cells[index]
        cell[3][cell[1]]=value
    end
    
    -- root.270. Corrected Rc semantics: true uses field 2, false uses field 14.
    -- Captures: sequence callback=root.R29, counter=root.R36,
    -- load ID=root.R2, active flag=root.R3, settings=root.R27.
    function M.bindTapLoop(env,cells)
        return function()
            while get(cells,4) and env.getgenv().EliteLoadId==get(cells,3) do
                if get(cells,5).AutoClick then
                    local delay=1/get(cells,5).TPS
                    put(cells,2,get(cells,2)+1)
                    local protectedCall=env.pcall
                    local remote=env.TapRequested
                    local fire=remote.FireServer
                    local request={}
                    request.Auto=false
                    request.ClientSequence=get(cells,1)()
                    protectedCall(fire,remote,request)
                    env.task.wait(delay)
                else
                    env.task.wait(0.5)
                end
            end
        end
    end
    
    -- root.55. PCs 1-18 build/send the request; 23-45 wait for a captured reply.
    function M.bindDiamondCraft(env,cells)
        return function(petIds)
            put(cells,1,nil)
            local protectedCall=env.pcall
            local remote=env.CraftRequested
            local fire=remote.FireServer
            local request={}
            request.Action="Craft"
            request.Machine="Diamond"
            request.PetIds=petIds
            protectedCall(fire,remote,request)
            local started=env.os.clock()
            while get(cells,1)==nil and env.os.clock()-started<5 do
                env.task.wait(0.01)
            end
            return get(cells,1)
        end
    end
    
    -- root.269. Same source operations as root.55; machine constant is Golden.
    function M.bindGoldenCraft(env,cells)
        return function(petIds)
            put(cells,1,nil)
            local protectedCall=env.pcall
            local remote=env.CraftRequested
            local fire=remote.FireServer
            local request={}
            request.Action="Craft"
            request.Machine="Golden"
            request.PetIds=petIds
            protectedCall(fire,remote,request)
            local started=env.os.clock()
            while get(cells,1)==nil and env.os.clock()-started<5 do
                env.task.wait(0.01)
            end
            return get(cells,1)
        end
    end
    -- root.75: 1.2-second request throttle, selected/best index, and 0.5-second polling.
    function M.bindAutoRebirth(env, cells)
        return function()
            local lastRequest = 0
            while get(cells, 2) and env.getgenv().EliteLoadId == get(cells, 3) do
                if get(cells, 1).AutoRebirth then
                    local index
                    if get(cells, 1).RebirthIndex == "Best Rebirth"
                        or get(cells, 1).RebirthIndex == "Best"
                        or get(cells, 1).RebirthIndex == nil then
                        index = env.GetMaxUnlockedRebirthIndex()
                    else
                        index = get(cells, 1).RebirthIndex
                    end
                    if index and env.CanRebirth(index) then
                        local now = env.os.clock()
                        if now - lastRequest >= 1.2 then
                            lastRequest = now
                            local protectedCall = env.pcall
                            local remote = env.RebirthRequested
                            local fire = remote.FireServer
                            protectedCall(fire, remote, {Index = index})
                        end
                    end
                end
                env.task.wait(0.5)
            end
        end
    end
    
    -- root.51: shared delete timestamps, a 3-second throttle, and hatch-aware polling.
    function M.bindAutoDelete(env, cells)
        return function()
            while get(cells, 4) and env.getgenv().EliteLoadId == get(cells, 3) do
                if env.PetActionRequested then
                    local enabled = get(cells, 5).AutoDelete
                        or get(cells, 5).DeleteGolden
                        or get(cells, 5).DeleteDiamond
                        or get(cells, 5).DeleteRainbow
                    if enabled and env.os.clock() - get(cells, 2).delAt >= 3 then
                        local timestamps = get(cells, 2)
                        local clockSource = env.os
                        timestamps.delAt = clockSource.clock()
                        timestamps.delLast = clockSource.clock()
                        env.pcall(get(cells, 1))
                    end
                end
                env.task.wait(get(cells, 5).AutoHatch and 1 or 3)
            end
        end
    end
    
    -- root.182: configured versus power-based equip, with live captured counters.
    -- normalizeIterator is the source-derived generalized iterator normalizer.
    function M.bindAutoEquip(env, cells, normalizeIterator)
        return function()
            while get(cells, 7) and env.getgenv().EliteLoadId == get(cells, 3) do
                if get(cells, 5).AutoEquipBest and env.PetActionRequested and not get(cells, 6)() then
                    local data = get(cells, 1)()
                    local owned = data and data.Pets and data.Pets.Owned
                    if owned then
                        local mode = env.tostring(get(cells, 5).AutoEquipMode or "Power")
                        if mode == "Power" then
                            local count = 0
                            local iterator, state, control = normalizeIterator(env.pairs(owned))
                            while true do
                                local key = iterator(state, control)
                                control = key
                                if key == nil then break end
                                count = count + 1
                            end
                            if count ~= get(cells, 2) or get(cells, 4) == "" then
                                put(cells, 2, count)
                                env.EquipBestPetsNow()
                            end
                        else
                            env.EquipConfiguredNow(false)
                        end
                    end
                end
