        local getmetatable, pairs, table = libs.getmetatable, libs.pairs, libs.table
        local M = {}
    
        function M.prepareGenericFor(registers, base, resultCount, nextPc, enterOffset, exitOffset)
            local iterator, state, control = registers[base], registers[base + 1], registers[base + 2]
            if type(iterator) ~= "function" then
                local metatable = getmetatable(iterator)
                if metatable ~= nil then
                    -- Preserve the original test/read pair, including __iter=false errors.
                    if metatable.__iter ~= nil then
                        iterator, state, control = metatable.__iter(iterator)
                    elseif metatable.__call == nil and type(iterator) == "table" then
                        iterator, state, control = pairs(iterator)
                    end
                elseif type(iterator) == "table" then
                    iterator, state, control = pairs(iterator)
                end
            end
            registers[base], registers[base + 1], registers[base + 2] = iterator, state, control
            local values = table.pack(iterator(state, control))
            for index = 1, resultCount do
                registers[base + 2 + index] = values[index]
            end
            registers[base + 2] = values[1]
            if values[1] ~= nil then
                return nextPc + enterOffset
            else
                return nextPc + exitOffset
            end
        end
    
        function M.prepareNumericFor(registers, base, nextPc, enterOffset, exitOffset)
            local start = registers[base]
            if type(start) ~= "number" then
                start = tonumber(start)
                registers[base] = start
            end
            local limit = registers[base + 1]
            if type(limit) ~= "number" then
                limit = tonumber(limit)
                registers[base + 1] = limit
            end
            local step = registers[base + 2]
            if type(step) ~= "number" then
                step = tonumber(step)
                registers[base + 2] = step
            end
            -- Keep the VM's zero-step/NaN comparison behavior; do not replace with a native for loop.
            local inRange
            if step > 0 then
                inRange = start <= limit
            else
                inRange = limit <= start
            end
            if inRange then
                return nextPc + enterOffset
            else
                return nextPc + exitOffset
            end
        end
        return M
    end
