-- BEGIN MODULE persistence.lua
moduleBuilders["persistence.lua"] = function()
    -- Readable persistence functions recovered from the original source/bytecode.
    -- No filesystem or JSON operation occurs until a returned function is called.
    local M = {}
    local function captured(cells, index)
        local cell = cells[index]
        return cell[3][cell[1]]
    end
    
    -- root.258: missing filesystem APIs retain the original behavior/errors.
    function M.bindEnsureFolder(runtime, env, cells)
        return function()
            if env.isfolder and not env.isfolder(env.CONFIG_FOLDER) then
                env.pcall(env.makefolder, env.CONFIG_FOLDER)
            end
        end
    end
    
    -- root.151: preserve generalized iteration and multi-return forwarding.
    function M.bindListConfigs(runtime, env, cells)
        return function()
            env.EnsureFolder()
            local names = {}
            if env.listfiles then
                local ipairs = env.ipairs
                local listFiles = env.listfiles
                local folder = env.CONFIG_FOLDER
                local iterator, state, control = runtime.normalize_iterator(ipairs(listFiles(folder)))
                while true do
                    local key, file = iterator(state, control)
                    control = key
                    if key == nil then break end
                    local path = env.tostring(file)
                    local name = path:match("([^/\\]+)%.json$")
                    if name and name ~= "_meta" then
                        env.table.insert(names, name)
                    end
                end
            end
            env.table.sort(names)
            return names
        end
    end
    
    -- root.134: JSON encoding is outside pcall, as in the original.
    function M.bindSaveMeta(runtime, env, cells)
        return function()
            env.EnsureFolder()
            local protectedCall = env.pcall
            local writeFile = env.writefile
            local path = env.META_FILE
            local httpService = captured(cells, 1)
            local metadata = {}
            local config = env.ConfigMeta
            metadata.AutoLoad = config.AutoLoad
            metadata.LoadName = config.LoadName
            local encode = httpService.JSONEncode
            protectedCall(writeFile, path, encode(httpService, metadata))
        end
    end
    
    -- root.173 and root.173.1: corrupt/missing metadata does not update ConfigMeta.
    function M.bindLoadMeta(runtime, env, cells)
        local table = runtime.libs.table
        return function()
            if env.isfile and env.isfile(env.META_FILE) then
                local success, metadata = env.pcall(function()
                    local httpService = captured(cells, 1)
                    local readFile = env.readfile
                    local path = env.META_FILE
                    local contents = table.pack(readFile(path))
                    -- Lookup follows readfile; preserve return counts and evaluation order.
                    local decode = httpService.JSONDecode
                    return decode(httpService, table.unpack(contents, 1, contents.n))
                end)
                if success and env.type(metadata) == "table" then
                    local config = env.ConfigMeta
                    config.AutoLoad = metadata.AutoLoad == true
                    config.LoadName = metadata.LoadName
                end
            end
        end
    end
    
    -- root.46 and root.46.1: snapshot, encode, write, then publish autoload metadata.
    function M.bindSaveConfig(runtime, env, cells)
        return function(name)
            if not name or name == "" then
                return false
            end
            env.EnsureFolder()
            local success, snapshot = env.pcall(env.Snapshot)
            if not success or env.type(snapshot) ~= "table" then
                env.warn("[Config] Snapshot error:", snapshot)
                return false
            end
            local encoded, contents = env.pcall(function()
                local httpService = captured(cells, 1)
                local value = snapshot
                local encode = httpService.JSONEncode
                return encode(httpService, value)
            end)
            if not encoded or not contents then
                env.warn("[Config] JSON encode error:", contents)
                return false
            end
            local protectedCall = env.pcall
            local writeFile = env.writefile
            local folder = env.CONFIG_FOLDER
            local path = folder .. ("/" .. (name .. ".json"))
            local written, writeError = protectedCall(writeFile, path, contents)
            if not written then
                env.warn("[Config] writefile error:", writeError)
                return false
            end
            local metadata = env.ConfigMeta
            metadata.LoadName = name
            metadata.AutoLoad = true
            env.SaveMeta()
            return true
        end
    end
    
    -- root.107: preserve all pcall return values, including the deletion error.
    function M.bindDeleteConfig(runtime, env, cells)
        return function(name)
            if not name or name == "" then
                return false
            end
            local folder = env.CONFIG_FOLDER
            local path = folder .. ("/" .. (name .. ".json"))
            if env.isfile and env.isfile(path) then
                return env.pcall(env.delfile, path)
            end
            return false
        end
    end
    -- root.25 and root.25.1: read/decode under pcall; ApplyData is outside it.
    function M.bindLoadConfig(runtime, env, cells)
        local table = runtime.libs.table
        return function(name)
            if not name or name == "" then return false end
            local folder = env.CONFIG_FOLDER
            local path = folder .. ("/" .. (name .. ".json"))
            if not (env.isfile and env.isfile(path)) then return false end
            local success, data = env.pcall(function()
                local httpService = captured(cells, 1)
                local readFile = env.readfile
                local contents = table.pack(readFile(path))
                local decode = httpService.JSONDecode
                return decode(httpService, table.unpack(contents, 1, contents.n))
            end)
            if not success then return false end
            return env.ApplyData(data)
        end
    end
    return M
end
-- END MODULE persistence.lua

