    return getModule("initialization.lua")(Recovery.defaults).initializeSettings(environment, eggNames)
end
function Recovery.createRuntime(environment)
    return getModule("runtime.lua")(getModule, environment)
end
function Recovery.createEntry(environment)
    local runtime = Recovery.createRuntime(environment)
    return runtime.make("root", environment, {}), runtime
end
