-- Reviewed bootstrap around the recovered source. Tests never call the recovered entry.
local App={}
function App.create(deps)
    local Recovery,gui=deps.recovery,deps.gui
    local Lifecycle,Bridge,Network,Gameplay,Config=deps.lifecycle,deps.bridge,deps.network,deps.gameplay,deps.config
    local PetFilters=deps.petFilters
