    local app={metadata=metadata,errors={},started=false,stopped=false}
    function app:report(err,path)
        table.insert(self.errors,{message=tostring(err),prototype=path})
        if deps.host.warn then deps.host.warn("[Elite recovery] "..tostring(path or "").." "..tostring(err))end
    end
    local life=Lifecycle.new(deps.host.task,metadata,function(err,path)app:report(err,path)end)
    app.lifecycle=life
    local env=setmetatable({},{__index=deps.host})
    app.environment=env;env.task=life:proxy()
    env.request=Network.wrap(deps.host.request);env.http_request=Network.wrap(deps.host.http_request)
    if type(deps.host.syn)=="table"then
        env.syn=table.clone(deps.host.syn);env.syn.request=Network.wrap(deps.host.syn.request)
    else env.syn=false end
    -- No recovered dynamic loader is needed; the user's GUI is embedded as source.
    env.loadstring=function()error("Recovered dynamic code loading is disabled")end
    env.load=env.loadstring
    local bridge=Bridge.new(gui,env.task,metadata,function(err)app:report(err)end)
    app.bridge=bridge;bridge.environment=env
    bridge.capabilities=deps.capabilities and deps.capabilities.check
    bridge.onDestroy=function()if not app.cleanupRunning then app:stop(false)end end
    local runtime=Recovery.createRuntime(env)
    app.runtime=runtime
    local baseMake=runtime.make
    local overrides={
        ["root.310"]=function()return function()return bridge:library()end end,
        ["root.116"]=Gameplay.bindClaimMachines,["root.207"]=Gameplay.bindHatchStart,
        ["root.88"]=Gameplay.bindHatchToggle,["root.233"]=Gameplay.bindRainbowCraft,
        ["root.24"]=PetFilters and PetFilters.bindDeleteNow,
    }
    if deps.protocols then
        overrides["root.37.5"]=deps.protocols.bindIslandPurchase
        overrides["root.37.6"]=deps.protocols.bindIslandNameRequest
        overrides["root.135.1"]=deps.protocols.bindIslandTravel
        overrides["root.132.13"]=deps.protocols.bindClaimIndex
        overrides["root.68.1"]=deps.protocols.bindEquipBestRequest
    end
    local configBindings={["root.258"]="EnsureFolder",["root.151"]="ListConfigs",["root.134"]="SaveMeta",["root.173"]="LoadMeta",["root.46"]="SaveConfig",["root.107"]="DeleteConfig",["root.25"]="LoadConfig"}
    for path,kind in pairs(configBindings)do
        overrides[path]=function()return Config.factory(kind,bridge,env)end
    end
    function runtime.make(path,environment,cells)
        local factory=overrides[path]
        local fn=factory and factory(runtime,environment,cells) or baseMake(path,environment,cells)
        if path=="root.187"then
            local build=fn
            fn=function(...)
                local result=table.pack(pcall(build,...))
                if not result[1]then app.guiBuildError=result[2];error(result[2],0)end
                app.guiBuilt=true
                return table.unpack(result,2,result.n)
            end
        end
        metadata[fn]={path=path,singleton=deps.singletonPaths[path]==true}
        if path=="root.250"then
            local cleanup=fn
            fn=function(...)
                if app.cleanupRunning or app.cleanupDone then return end
                app.cleanupRunning=true
                bridge:saveFinal()
                local result=table.pack(pcall(cleanup,...))
                app.cleanupRunning=false;app.cleanupDone=true;app.stopped=true
                life:stop()
                if not result[1]then app:report(result[2],path);error(result[2],0)end
                return table.unpack(result,2,result.n)
            end
            metadata[fn]={path=path,singleton=false};app.recoveredCleanup=fn
        end
        return fn
    end
    -- Original GUI construction calls are redirected to AirFlow, including original captured callbacks.
    runtime.guiBridge=bridge
    function app:start()
        if self.started then return self end
        assert(not self.stopped,"Cannot restart a stopped recovery session")
        self.started=true
        local entry=runtime.make("root",env,{})
        local ok,err=pcall(entry)
        if not ok then self:report(err,"root");self:stop(true);return nil,err end
        if self.guiBuildError then self:stop(true);return nil,self.guiBuildError end
        if not bridge.window or not self.guiBuilt then self:stop(true);return nil,"Recovered startup exited before constructing the custom GUI"end
