end
function App.checkHost(host)
    local missing={}
    for _,key in ipairs({"game","task","getgenv","table","string","bit32","math","os","Vector3","CFrame","Enum","Instance"})do
        if host[key]==nil then table.insert(missing,key)end
    end
    if host.task and(type(host.task.spawn)~="function"or type(host.task.cancel)~="function")then table.insert(missing,"task.spawn/cancel")end
    for _,key in ipairs({"isfile","readfile","writefile","isfolder","makefolder","listfiles","delfile"})do
        if type(host[key])~="function"then table.insert(missing,key.." (persistent AirFlow configuration)")end
    end
    return #missing==0,missing
end
return App

end)()
