 [835]={"DoubleJumpPurchaseRF.InvokeServer"},[1255]={"PetIndexClaimAll.FireServer"},
 [1317]={"QuestClaimRF.InvokeServer"},[1683]={"EggHatchRequested.FireServer"},
 [2063]={"CraftRequested.FireServer"},[2298]={"CraftRequested.FireServer"},[2499]={"CraftRequested.FireServer","@GetOwnedPetsByNameAndTier","@GoToRainbow"},
