        local ok,value=pcall(function()return parent and env[parent]and env[parent][member]or(not parent and env[name]or nil)end)
        if not ok or value==nil or value==false or ((functionOnly or member)and type(value)~="function")then table.insert(missing,name)end
    end
    if pc==3915 or pc==3963 then
        local sender=type(env.request)=="function"or type(env.http_request)=="function"or(type(env.syn)=="table"and type(env.syn.request)=="function")
        if not sender then table.insert(missing,"HTTP sender (explicit Discord webhook only)")end
    end
