modules["config_bridge"] = (function()
-- Routes legacy profile callbacks through AirFlow's original configuration implementation.
local M={}
function M.factory(kind,bridge,env)
    local function window()return assert(bridge.window,"Custom GUI is not ready for configuration operations")end
    if kind=="EnsureFolder"then return function()
        assert(type(env.isfolder)=="function" and type(env.makefolder)=="function","Configuration folder APIs unavailable")
        local folder=bridge.window and bridge.window.ConfigFolder or "EliteHubAirFlow"
        if not env.isfolder(folder)then env.makefolder(folder)end
        return true
    end end
    if kind=="ListConfigs"then return function()if not bridge.window then return {}end;return window():ListConfigs()end end
    if kind=="SaveConfig"then return function(name)
        local ok,err=window():SaveConfig(name)
        if not ok then return false,err end
        env.ConfigMeta.LoadName=name;env.ConfigMeta.AutoLoad=true
        local saved,metaError=window():SetAutoload(name)
        if not saved then return false,metaError end
        return true
    end end
    if kind=="LoadConfig"then return function(name)return window():LoadConfig(name,false)end end
    if kind=="DeleteConfig"then return function(name)return window():DeleteConfig(name)end end
    if kind=="LoadMeta"then return function()
        if not bridge.window then return end
        local name=window():GetAutoload();env.ConfigMeta.AutoLoad=name~=nil;env.ConfigMeta.LoadName=name
    end end
    if kind=="SaveMeta"then return function()
        local name=env.ConfigMeta.AutoLoad and env.ConfigMeta.LoadName or nil
        return window():SetAutoload(name)
    end end
    error("Unknown config binding: "..kind)
end
return M

end)()
modules["gameplay"] = (function()
-- Additional reviewed gameplay recovery; source references in evidence/gameplay_provenance.json.
local M={}
local function get(cells,n)local c=cells[n];return c[3][c[1]]end
local function put(cells,n,value)local c=cells[n];c[3][c[1]]=value end
function M.bindClaimMachines(runtime,env,cells)
    return function()
        while get(cells,2) and env.getgenv().EliteLoadId==get(cells,3) do
            if get(cells,1).AutoClaimMachines then env.pcall(env.ClaimShinyReadyCrafts) end
            env.task.wait(3)
        end
    end
end
function M.bindHatchStart(runtime,env,cells)
    return function()
        put(cells,2,true);get(cells,3).AutoHatch=true
        env.task.spawn(get(cells,1))
        return true
    end
end
function M.bindHatchToggle(runtime,env,cells)
    return function(enabled)
        get(cells,2).AutoHatch=enabled
        if not enabled then
            put(cells,3,false)
            -- Intentional lifecycle repair: cancel a sleeping worker instead of leaving a restart race.
            if env.task.cancelUnique then env.task.cancelUnique("root.76") end
        else put(cells,1,true) end
    end
end
function M.bindRainbowCraft(runtime,env,cells)
    return function(name,count)
        if not get(cells,2).RainbowEnabled then return false end
        local owned=env.GetOwnedPetsByNameAndTier(name,"Diamond")
        count=env.math.min(count or 5,#owned)
        if count<2 then return false end
        put(cells,3,true)
        local previous
        local function restore()
            local current=get(cells,1).Character
            current=current and get(cells,1).Character:FindFirstChild("HumanoidRootPart")
            if previous and current and current.Parent then
                current.AssemblyLinearVelocity=env.Vector3.zero
                current.AssemblyAngularVelocity=env.Vector3.zero
                current.CFrame=previous;env.task.wait(0.2)
            end
        end
        local ok,result=pcall(function()
            local character=get(cells,1).Character
            local root=character and character:FindFirstChild("HumanoidRootPart")
            previous=root and root.CFrame
            env.GoToRainbow();env.task.wait(0.35)
            -- Safety repair: disabling during travel must prevent a new craft request.
            if not get(cells,2).RainbowEnabled then restore();return false end
            local ids={}
            for i=1,count do ids[i]=owned[i]end
            local remote=env.CraftRequested
            env.pcall(remote.FireServer,remote,{Machine="Shiny",Action="Craft",PetIds=ids})
            env.task.wait(0.5);restore()
            return true
        end)
        put(cells,3,false)
        if not ok then env.pcall(restore);error(result,0)end
        -- Means the client flow completed, not that the server accepted the craft.
        return result
    end
end
return M

end)()
