-- Owns only this recovery session's tasks. No worker is started by loading this module.
local Lifecycle = {}
Lifecycle.__index = Lifecycle
function Lifecycle.new(taskApi, metadata, onError)
    return setmetatable({task=taskApi, metadata=metadata, onError=onError or warn,
        tasks={}, unique={}, stopped=false, generation=0}, Lifecycle)
end
function Lifecycle:spawn(fn, ...)
