    local meta=self.metadata[fn]
    local key=meta and meta.singleton and meta.path
    if key and self.unique[key] then return self.unique[key].thread end
    local record={key=key, generation=self.generation}
    if key then self.unique[key]=record end
    self.tasks[record]=true
    local args=table.pack(...)
    local thread=self.task.spawn(function()
        if self.stopped or record.generation~=self.generation then return end
        local ok,err=pcall(fn,table.unpack(args,1,args.n))
        self.tasks[record]=nil
        if key and self.unique[key]==record then self.unique[key]=nil end
        if not ok and not self.stopped then self.onError(tostring(err),meta and meta.path) end
    end)
    record.thread=thread
    return thread
end
function Lifecycle:cancelUnique(key)
    local r=self.unique[key]
    if r then
        self.unique[key]=nil; self.tasks[r]=nil
        if r.thread then pcall(self.task.cancel,r.thread) end
    end
end
function Lifecycle:stop()
    if self.stopped then return end
    self.stopped=true; self.generation+=1
    for r in pairs(self.tasks) do if r.thread then pcall(self.task.cancel,r.thread) end end
