modules["network"] = (function()
-- Only explicit Discord webhook POSTs are permitted through recovered HTTP senders.
-- No request is made on rejection, and no fake server response is returned.
local Network = {}
function Network.allowed(request)
    if type(request)~="table" or type(request.Url)~="string" then return false end
    local method=string.upper(request.Method or "GET")
    if method~="POST" then return false end
    return request.Url:match("^https://discord%.com/api/webhooks/%d+/[%w_%-]+$")~=nil
        or request.Url:match("^https://discordapp%.com/api/webhooks/%d+/[%w_%-]+$")~=nil
end
function Network.wrap(sender)
    if type(sender)~="function" then return nil end
    return function(request)
        assert(Network.allowed(request), "Recovered HTTP request blocked: only explicit Discord webhook POSTs are allowed")
        return sender(request)
    end
end
return Network

end)()
