-- Recovered root.24 deletion planner and packet flow, including root.24.1 strongest/secret protection.
-- Safety deltas: fail closed if strongest-pet protection fails; release busy on errors; stop between batches.
local M={}
local function get(c,n)local x=c[n];return x[3][x[1]]end
local function put(c,n,v)local x=c[n];x[3][x[1]]=v end
local function listSet(env,values,stringKeys)
    local set={}
    for _,value in env.ipairs(env.type(values)=="table"and values or {})do
        set[stringKeys and env.tostring(value)or value]=true
    end
    return set
end
function M.bindDeleteNow(runtime,env,cells)
    return function()
        if get(cells,4)or not env.PetActionRequested or not get(cells,3)then return end
        local settings=get(cells,5)
        if not(settings.AutoDelete or settings.DeleteGolden or settings.DeleteDiamond or settings.DeleteRainbow)then return end
        local data=get(cells,2)()
        if not data or not data.Pets or not data.Pets.Owned then return end
        put(cells,4,true)
        local ok,err=pcall(function()
            local groups={
                {flag="AutoDelete",on=settings.AutoDelete,tier="Normal",rarities=settings.DeleteRarities},
                {flag="DeleteGolden",on=settings.DeleteGolden,tier="Golden",rarities=settings.DeleteGoldenRarities},
                {flag="DeleteDiamond",on=settings.DeleteDiamond,tier="Diamond",rarities=settings.DeleteDiamondRarities},
                {flag="DeleteRainbow",on=settings.DeleteRainbow,tier="Shiny",rarities=settings.DeleteRainbowRarities},
            }
            local names=listSet(env,settings.DeleteWhitelistNames,true)
            local rarities=listSet(env,settings.DeleteWhitelistRarities,true)
            local enchanting=listSet(env,settings.EnchPets,false)
            local strongest={}
            local protected,protectionError=env.pcall(function()
                local limit=env.tonumber(data.Pets.EquipLimit)or 5
                local ordered,keep={},{}
                for id,pet in env.pairs(data.Pets.Owned)do
                    local rarity=env.tostring(pet.Rarity or "")
                    if rarity:find("^Secret")then keep[id]=true end
                    ordered[#ordered+1]=id
                end
                env.table.sort(ordered,function(a,b)
                    return env.PetRealPower(data.Pets.Owned[a])>env.PetRealPower(data.Pets.Owned[b])
                end)
                for i=1,env.math.min(limit,#ordered)do keep[ordered[i]]=true end
                for id in env.pairs(keep)do strongest[id]=true end
            end)
            assert(protected,"Deletion stopped: strongest/secret protection failed: "..tostring(protectionError))
            for _,group in env.ipairs(groups)do
                if group.on and env.type(group.rarities)=="table"and #group.rarities>0 then
                    local selected=listSet(env,group.rarities,true)
                    local equipped={}
                    if env.type(data.Pets.Equipped)=="table"then
                        for _,id in env.pairs(data.Pets.Equipped)do if env.type(id)=="string"then equipped[id]=true end end
                    end
                    local indexName
                    if get(cells,5).AutoIndex then indexName=get(cells,1)end
                    local ids={}
                    for id,pet in env.pairs(data.Pets.Owned)do
                        local isEquipped=pet.Equip==true or pet.Equipped==true or equipped[id]==true
                        local tier=pet.Tier or "Normal"
                        local indexProtected=indexName~=nil and pet.Name==indexName
                        local whitelisted=names[pet.Name]==true or rarities[pet.Rarity]==true
                        local enchantProtected=enchanting[id]==true
                        if selected[env.tostring(pet.Rarity)] and tier==group.tier and not pet.Locked
                            and not isEquipped and not indexProtected and not whitelisted
                            and not enchantProtected and not strongest[id]then
                            env.table.insert(ids,id)
                        end
                    end
                    for offset=1,#ids,50 do
                        if not get(cells,3)or not get(cells,5)[group.flag]then break end
                        local batch={}
                        for i=offset,env.math.min(offset+49,#ids)do env.table.insert(batch,ids[i])end
                        local remote=env.PetActionRequested
                        env.pcall(remote.FireServer,remote,{Action="Delete",PetIds=batch})
                        env.task.wait(0.08)
                    end
                end
            end
        end)
        put(cells,4,false)
        if not ok then error(err,0)end
    end
end
return M

end)()
