local CustomRecovery = {status="partially_functional_integration", liveValidated=false}
function CustomRecovery.start(host)
    host=host or getfenv()
    local ok,missing=modules.app.checkHost(host)
    if not ok then return nil,"Missing host dependencies: "..table.concat(missing,", ")end
    local shared=host.getgenv()
    local previous=shared.__EliteAirFlowRecovery
    if previous then
        local stopped,err=pcall(previous.stop,previous,true)
        if not stopped then return nil,"Prior session cleanup failed: "..tostring(err)end
    end
    local gui=modules.gui_cache.get(shared,"d89c652ade48090c5934a6361f3745c4767c5e9c",userGuiSource)
    local app=modules.app.create({host=host,recovery=recoveredSource(),gui=gui,
        lifecycle=modules.lifecycle,bridge=modules.gui_bridge,network=modules.network,
        gameplay=modules.gameplay,config=modules.config_bridge,petFilters=modules.pet_filters,protocols=modules.protocols,capabilities=modules.capabilities,singletonPaths=singletonPaths})
    shared.__EliteAirFlowRecovery=app
    local started,err=app:start()
    if not started then
        if shared.__EliteAirFlowRecovery==app then shared.__EliteAirFlowRecovery=nil end
        return nil,err
    end
    return app
end
-- Roblox/executor execution starts this reviewed bootstrap. CLI validation only compiles this file.
if game ~= nil then
    local ok,app,err=pcall(CustomRecovery.start,getfenv())
    if not ok then warn("[Elite recovery] "..tostring(app))
    elseif not app then warn("[Elite recovery] "..tostring(err))end
end
return CustomRecovery
